, NULL, NULL, 'EN', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1080/17483107.2022.2111723', NULL, NULL, NULL, NULL, 'https://doi.org/10.1080/17483107.2022.2111723', '2026-09-18', NULL, NULL, 2, 'sr_meta', NULL, NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 04:05', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'crossref-api', NULL, 1, NULL, '604-622', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
