INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-01000', NULL, NULL, 0, NULL, NULL, 0, NULL, 2016, NULL, 'The Effect of Transport Accessibility on the Social Inclusion of Wheelchair Users: A Mixed Method Analysis', NULL, NULL, NULL, 'EN', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.17645/si.v4i3.484', NULL, NULL, NULL, NULL, 'https://doi.org/10.17645/si.v4i3.484', '2026-09-18', NULL, NULL, 3, 'clinical', NULL, NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 04:09', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'crossref-api', NULL, 1, NULL, '24-35', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'lower_control', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-008', 'SW', 'P1', 'OPEN', NULL, NULL, 'source_locators.doi IS SHUFFLED RELATIVE TO title/authors/pub_year ACROSS THE PRE-RESET MIGRATION, AND IT BREAKS R9 IN BOTH DIRECTIONS. Found by the write path, not by a check: db.py add-source refused REF-00999 (Rouvier 2022) because DOI 10.1371/journal.pone.0269657 is ''already filed as REF-00037'', and refused Kim 2014''s 10.1016/j.ergon.2014.07.001 as ''already filed as REF-00030''. BOTH REFUSALS ARE FALSE. On each row the doi+issn pair is internally consistent and correct for the NEW source, while title/authors/pub_year describe a DIFFERENT work: REF-00037 carries the PLoS One DOI and ISSN 1932-6203 under the title ''Inclusive Housing Design Guide'' (Runnalls & Walker 2024, which embeds its OWN different DOI 10.4324/9781003564164 inside the title string); REF-00030 carries the Int J Industrial Ergonomics DOI and ISSN 0169-8141 under a speech-intelligibility/classroom-acoustics title (Murgia et al.). CONSEQUENCE, and the second half is the worse one: R9 dedup fires FALSE COLLISIONS that block correct admissions (2 of 5 candidate DOIs in this batch), and by the same shuffle it must also FALSE-CLEAR real duplicates whose DOI landed on some other row -- silently failing the check R9 exists to be. SCALE: derive it, never quote it. The exposed population is rows where doi is not null; the subset whose title embeds a DIFFERENT doi than the doi column is the ONLY mechanically detectable signature, so that count is a FLOOR, not an estimate -- rows whose title embeds no DOI are undetectable by it. Nearly all exposed rows carry recovered_from=''corpus-pre-reset-2026-08-06''. REPAIR IS BLOCKED ON A WRITER: db.py has no command that can set source_locators.doi or .title, and correct-source operates on evidence_sources only. source_locators_integrity has been reporting this at ADVISORY level as a title-quality issue; it is actually a DOI-reliability defect that breaks a blocking gate, and the framing understated it.', '2026-09-18 04:15', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:15', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-009', 'SW', 'P1', 'OPEN', NULL, NULL, 'EVERY SOURCE ADMITTED BEFORE 2026-09-18 WAS FILED TO EXACTLY ONE SLUG, AND THE CAUSE WAS A MISSING WRITER RATHER THAN A RESEARCH JUDGEMENT. Measured before this batch: select n, count(*) from (select ref_id, count(distinct slug) n from source_slug_links group by ref_id) group by n returned ONE row -- every source linked to 1 slug, not one to 2. Mechanism: db.py add-source refuses a second call for an existing ref_id with the instruction ''R9: cross-file the existing ref_id rather than duplicating'', and NO COMMAND IMPLEMENTED THAT INSTRUCTION. The CLI named the correct action and could not perform it, so single-slug filing was the only expressible outcome and the corpus shape recorded a tooling limit as though it were an editorial decision. Owner directive 2026-09-18: ''you search by slug, but you have to adjudicate by all slugs in a category and stuff for each source''; ''wherever is relevant to accessibility can be mined from it''; ''we should be able to file multiple rows per source based on what category it is being filed for''. FIXED FORWARD HERE by db.py link-source-slug (derives local_ref_id per rule 8, demands --rationale naming which claim bears on the target slug, and refuses an unadmitted ref_id, an unregistered slug, or a duplicate link). THE BACKLOG IS NOT FIXED: every source from batches 01-14 still needs adjudicating against the full slug registry. A SECOND BACKLOG follows from the same directive -- the zero-admission searches whose own findings_note records that material WAS retrieved and read and was then dropped as off-parameter, which under this directive is no longer a sufficient reason to discard. Derive both counts; do not quote them.', '2026-09-18 04:15', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:15', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (60, 'accessible-circulation-geometry', NULL, 'EN', 2, 'sr_meta', NULL, '(wheelchair OR "mobility device") AND (ramp OR slope OR incline OR gradient) AND (review OR synthesis OR guideline OR recommendation)', NULL, 'pubmed', 'systematic', 'none', 107, 25, 0, 'partial', NULL, NULL, 0, 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:03', 'PRIOR FALSIFIED ON VOLUME (informatively), CONFIRMED ON CONTENT. 107 hits against exec 30''s 1 -- an order of magnitude above the upper bound I predicted, which SETTLES BY MEASUREMENT that exec 30 characterised its own query shape and not the literature. R14: QUERY-SHAPE FAILURE, now demonstrated rather than asserted. REF-00984 (Kilkens) reappeared and the R9 pre-check caught it as already held. The strongest hit, Rouvier 2022 (PLoS One, 34 studies, barriers classified by slope/cross-slope/curb/ground), was RETRIEVED IN FULL from PMC9223621 and READ: it states NO gradient value anywhere, exactly as the prior predicted. It carries a first-class R7 code-insufficiency finding at T2 instead. ZERO ADMITTED HERE ONLY BECAUSE ITS ADMISSION IS BLOCKED -- see GAP-008: its DOI collides with a corrupted source_locators row. Staged as candidate pending that repair.', 0, 'Exec 30''s single hit is an artefact of its [Publication Type] gate, not of the literature. Removing the gate returns MORE THAN ONE review-shaped record: expect 3-15 hits. Expect NONE to state a gradient ceiling -- the propulsion literature measures effects across ranges. FALSIFIED IF a T2 record states a maximum or recommended gradient.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (61, 'accessible-circulation-geometry', NULL, 'EN', 2, 'sr_meta', NULL, '(ramp OR slope OR gradient) AND (maximum OR threshold OR limit OR criterion) AND (wheelchair OR accessibility OR "built environment")', NULL, 'pubmed', 'scoping', 'none', 3008, 25, 0, 'none', NULL, NULL, 0, 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:03', 'PRIOR FALSIFIED ON YIELD, AND THE FAILURE IS THE QUERY''S NOT THE LITERATURE''S. I predicted 0-5 hits; PubMed returned 3008. R14 SAYS WHICH KIND: QUERY-SHAPE FAILURE. PubMed expanded ''accessibility'' to the MeSH term Architectural Accessibility OR the free-text stem access/accessed/accessible/accessing, and ''limit'' to limit/limitation/limited/limiting -- so the third clause matched essentially any paper using the word access and the second matched any paper with a limitation. The AND-chain did not narrow; it broadened. Recorded UNSCREENED BEYOND THE FIRST 25 and deliberately NOT retried in the same shape (R14: do not re-run a malformed query and read its noise as absence). The concept this query was reaching for was answered instead by exec 62 on a semantic engine.', 0, 'Searching threshold/maximum/limit language rather than propulsion mechanics reaches a different literature -- rehabilitation engineering and accessibility standards research. Expect LOW YIELD (0-5) and expect any hit to be a standards-development paper citing a code value rather than deriving one, which would be T2 restating T6 and NOT an anchoring-tier stated value. FALSIFIED IF a study derives a threshold from its own data.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (62, 'accessible-circulation-geometry', NULL, 'EN', 2, 'sr_meta', NULL, 'maximum ramp slope gradient wheelchair users can safely negotiate threshold', NULL, 'consensus', 'systematic', 'none', 10, 10, 1, 'partial', NULL, NULL, 0, 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:03', 'PRIOR FALSIFIED, AND THIS IS THE BATCH''S MOST IMPORTANT RESULT. I predicted 0 new admissions and overlap; the overlap half held (REF-00983 Bertocci 2018 returned, confirming saturation on the propulsion seam) but the engine reached TWO sources that DERIVE A MAXIMUM GRADIENT FROM THEIR OWN EXPERIMENTAL DATA, which is exactly what spec 7''s falsification condition names and what nine batches had not found. Kim et al. 2014 (Int J Industrial Ergonomics 44(5):636-646, 30 participants, slopes 1:6-1:14 x heights 0.15/0.30/0.45 m): ''we suggest maximum allowable slope by ramp height: 1:8, 1:10 and 1:12 were recommended for the heights of 0.15 m, 0.30 m, and 0.45 m, respectively''. Vredenburgh et al. 2009 (J Architectural and Planning Research): ''for a transit distance up to 6 m (20 ft), a ramp should not exceed a maximum cross slope of 5% or a maximum running slope of 7%''. NEITHER IS IN PUBMED -- ergonomics and architecture/planning are outside its biomedical scope, which is WHY ten batches of PubMed and open-web work missed them. ONE ADMISSION HERE (REF-00999, Frost 2020, R7 harm); Kim and Vredenburgh are BLOCKED, Kim by GAP-008''s corrupted locator DOI and Vredenburgh by R10 (unresolvable in Crossref). Both staged.', 0, 'A semantic engine will surface the dose-response literature already held (REF-00983/985/986) and I expect SUBSTANTIAL OVERLAP with the corpus -- a saturation signal, not a failure. Expect 0 NEW ADMISSIONS and I will record overlap explicitly. FALSIFIED IF it surfaces a synthesis the PubMed queries structurally could not reach.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (63, 'accessible-circulation-geometry', NULL, 'EN', 2, 'sr_meta', NULL, 'What ramp gradient or slope threshold is recommended as a maximum for manual wheelchair users in the built environment, and is there evidence that code-permitted gradients are insufficient for independent self-propulsion?', NULL, 'scholar-gateway', 'systematic', 'none', 15, 15, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:04', 'PRIOR FALSIFIED, AND IN THE OPPOSITE DIRECTION FROM THE ONE I FEARED. I predicted this would be the batch''s richest query; it was the poorest. The engine returned 15 passages that collapse to roughly four distinct papers, all Hindawi propulsion-biomechanics (treadmill slope kinematics/EMG, wearable sensors, frame material/vibration), heavily duplicated across passages, NONE stating or arguing a gradient threshold. SATURATED on the seam already held by REF-00983/985/986. THE CROSS-DISCIPLINARY REACH I PREDICTED HERE WAS DELIVERED BY exec 62 (Consensus) INSTEAD -- the ergonomics and architecture/planning literature this query was designed to find came back from a different engine entirely. Recorded because the mis-prediction is about ENGINE SELECTION, not about the literature: a semantic full-text passage engine optimised for biomedical corpora reproduces PubMed''s disciplinary boundary rather than crossing it.', 0, 'Ramp-gradient thresholds may be studied outside rehabilitation medicine -- in ergonomics, transport, universal-design research -- where PubMed does not index. Expect THE HIGHEST PROBABILITY OF A GENUINELY NEW SOURCE OF ANY QUERY IN THIS BATCH, and also the highest risk of T3 grey. FALSIFIED IF it returns only what PubMed already gave.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (64, 'accessible-circulation-geometry', NULL, 'EN', 2, 'sr_meta', NULL, 'wheelchair users lived experience ramps inaccessible despite meeting accessibility standards critique', NULL, 'consensus', 'systematic', 'none', 10, 10, 2, 'partial', NULL, NULL, 0, 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:16', 'PRIOR CONFIRMED AND THE DIRECTIVE WAS IMMEDIATELY VINDICATED: the single richest query of the batch, and it was reachable the whole time under the value-first framing that had been filtering it out. TWO ADMISSIONS. REF-00977 (Kapsalis 2022) is a T2 systematic review of 48 MMAT-appraised studies arguing the built environment is itself a FACTOR OF DISABLEMENT, naming boarding ramps and entrance features among the least accessible elements -- an ANCHORING-TIER source that states no value and would have been discarded by this batch''s original framing. It cross-files to REF-00977, the ref_id the 2026-09-13 corpus clear deliberately retained for exactly this re-admission. REF-01000 (Velho 2016) is mixed-methods and supplies the batch''s sharpest single sentence: ''proposed solutions to accessibility, such as ramps, often generate problems of their own'', paired with a measured load of 2 to 3 times body weight through the shoulders linked to shoulder injury -- the ramp as an iatrogenic accommodation. STAGED NOT ADMITTED: Faranda 2025 (possible Co-1 collaborative action research, closed access, co-production unverifiable from the abstract), plus Velho 2019, Flemmer 2022, Tatano 2022 and Lenker 2016. R7 yield is high throughout.', 0, 'ADDED MID-BATCH ON AN OWNER DIRECTIVE, and the prior is written before running it. Owner, 2026-09-18: ''we are looking not only for values and parameters, but also logics and arguments and qualitative work'' and ''if a source speaks towards ramps with a high level of relevancy even tho there is no stated value then surely there is qualitative reasoning that is worthwhile''. This supersedes PRIORS.md section 2, which scoped the batch to a STATED VALUE and would have discarded exactly this material. Expect 2-5 sources that are highly relevant to ramps, state no gradient, and carry argument or lived-experience reasoning. Expect the dominant shape to be code-compliance-is-not-usability. FALSIFIED IF the qualitative literature turns out to be thin or to merely restate the biomechanics already held.');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-18-resea-REF-00977-MOB', 'REF-00977', 'MOB', 'users of mobility assistive devices across 48 reviewed studies, predominantly wheelchair users in high-income countries', 48, 'PARTIAL', 'PARTIAL rather than EXACT and the review says why itself: it notes the reviewed studies mostly focused on wheelchair users residing in high-income countries, so the synthesis under-represents the majority world. sample_size records 48 STUDIES, not participants -- a synthesis has no participant count of its own.', '2026-09-18 04:14', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'REF-00977', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-18-resea-REF-00999-MOB', 'REF-00999', 'MOB', 'wheelchair users who ride transit buses (self-selected internet survey; manual and powered)', 384, 'EXACT', 'The study population IS the served population: 384 wheelchair users reporting on their own ramp use. This is the rare EXACT grade in this corpus -- most ramp evidence is measured on able-bodied proxies. Limitation stated rather than hidden: internet-based self-selected recruitment, and the setting is transit-bus ramps rather than fixed building ramps, so the gradient regime is steeper than the built-environment codes permit.', '2026-09-18 04:14', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'REF-00999', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-18-resea-REF-01000-MOB', 'REF-01000', 'MOB', 'wheelchair users in London using public transport; interviews plus push-force measurement', NULL, 'PARTIAL', 'PARTIAL: the interview half studies the served population directly, but the paper does not report how many wheelchair users provided the push-force measurements, so the quantified half cannot be graded on sample. Single-city (London) and transit-specific.', '2026-09-18 04:14', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'REF-01000', NULL);
