INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (64, 'REF-00977', '2026-09-18 04:16', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (64, 'REF-01000', '2026-09-18 04:16', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (88, 62, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Kim CS, Lee D, Kwon S, Chung MK (2014). Effects of ramp slope, ramp height and users'' pushing force on performance, muscular activity and subjective ratings during wheelchair driving on a ramp. Int J Industrial Ergonomics 44(5):636-646', '10.1016/j.ergon.2014.07.001', NULL, 2, 0, 'BLOCKED BY GAP-008, not by judgement. Its DOI collides with corrupted locator row REF-00030, so add-source refuses it as a duplicate of a speech-intelligibility paper. Bibliography independently VERIFIED via Crossref and Unpaywall (both confirm title/journal/vol 44(5)/pp636-646/Elsevier); full text CLOSED, 0 OA locations, so the VALUE is not verified from the source.', 'HIGHEST-VALUE OUTSTANDING CANDIDATE IN THE CORPUS. R15 HYPOTHESIS, stated as one: the Consensus abstract reports ''we suggest maximum allowable slope by ramp height: 1:8, 1:10 and 1:12 were recommended for the heights of 0.15 m, 0.30 m, and 0.45 m, respectively'', derived from 30 participants across slopes 1:6-1:14. If that holds against the source it is an ANCHORING-TIER DERIVED VALUE and it satisfies specification 7''s own falsification condition, which no source in nine batches has met. It is RISE-CONDITIONED, the same shape as REF-00990 and REF-00997. NOT ADMITTED AND NOT TO BE CITED until the publisher text is read: the figure currently rests on an aggregator abstract, which is not a rung on the R10 ladder, and batch 13''s Foundations falsification is the standing warning that a plausible numerate snippet can be wrong.', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:16');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (89, 62, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Vredenburgh AG et al. (2009). Evaluation of wheelchair users'' perceived sidewalk and ramp slope: effort and accessibility. Journal of Architectural and Planning Research', 'NOT RESOLVABLE IN CROSSREF as of 2026-09-18', NULL, 2, 0, 'R10 NOT SATISFIED: the DOI ladder terminates. Crossref returns no match for the title or the author; the journal is outside PubMed''s biomedical scope. No re-retrieval means no admission.', 'R15 HYPOTHESIS: the Consensus abstract reports ''for a transit distance up to 6 m (20 ft), a ramp should not exceed a maximum cross slope of 5% or a maximum running slope of 7%''. If confirmed this is a SECOND anchoring-tier derived value AND the corpus''s first cross-slope figure -- a distinct parameter from running gradient that parameter 3 does not cover. Needs a library route or the publisher; re-describe from the source on resolution.', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:16');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (90, 64, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Faranda I, Egard H, Pareschi L, Sicca LM (2025). Resistance to accessibility improvements in publicly accessible buildings. Disability & Society 41(2):381-407', '10.1080/09687599.2025.2509552', NULL, 1, 1, 'CLOSED ACCESS (Unpaywall: is_oa false, 0 OA locations) and the Co-1 question cannot be settled from an abstract. Claiming Co-1 on the abstract''s wording alone is the failure CLAUDE.md section 6 calls the worst available here.', 'POSSIBLE Co-1, THEREFORE HIGH PRIORITY. Abstract describes ''collaborative action research involving wheelchair users'' and says disabled activists conducted the research themselves. If co-production is evidenced in the paper this is Co-1, co-primary with T1 under CRPD Art 4.3, and add-source will demand --co1-provenance NAMING the people or organisation, which the abstract does not. Substantively an ARGUMENT source of the kind the 2026-09-18 directive prioritises: it explains WHY barrier removal is resisted -- conflicting interpretations of what accessibility is and of what wheelchair users may legitimately expect -- and reports 71% of 448 mapped establishments without an accessible entrance, mostly over a single step.', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:17');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (91, 64, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Velho R (2019). Transport accessibility for wheelchair users: A qualitative analysis of inclusion and health. International Journal of Transportation Science and Technology', 'DOI not yet confirmed -- do NOT reuse the guessed 10.1016/j.ijtst.2019.02.001 without a Crossref check', NULL, 3, 1, 'Not retrieved this batch; sibling of REF-01000 by the same first author and the independence question must be settled before both are weighed (see the convergence-independence rule).', 'Pure QUALITATIVE: barriers, the negative emotions they produce, and the problem-solving techniques wheelchair users develop in response. R15 hypothesis. Note the author overlap with REF-01000 (Velho) and, separately, that REF-00999 (Frost) shares an author with REF-00983 (Bertocci) -- two independence questions the synthesis stage must not treat as four independent voices.', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:17');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (92, 64, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Flemmer CL (2022). Improving the built environment for manual wheelchair users: A review. IOP Conf Ser Earth Environ Sci', 'DOI not confirmed', NULL, 3, 0, 'Not retrieved this batch.', 'ARGUMENT source: separates three distinct causes of inaccessibility -- intrinsic user capability, features that FAIL to comply with code, and features that COMPLY yet are defeated by obstruction or poor maintenance. That third category is a distinct failure mode the corpus does not yet hold and it bears directly on why a compliant gradient can still be unusable.', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:17');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (93, 64, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Tatano V, Revellini R (2022). An alternative system to improve accessibility for wheelchair users: The stepped ramp. Applied Ergonomics 108:103938', '10.1016/j.apergo.2022.103938', NULL, 2, 0, 'Not retrieved this batch; R9 clear against both evidence_sources and source_locators.', 'Studies ramps in Venice built DELIBERATELY STEEPER than regulation because the urban morphology forbids a compliant run, and evaluates comfort and floor-surface friction across ten of them. Directly relevant to the conditional/exception shape already held from REF-00990 and REF-00997, and to the question of what to do when the compliant value is unbuildable.', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:17');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (94, 64, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Lenker JA et al. (2016). Usability evaluation of access ramps in transit buses: Preliminary findings. Journal of Public Transportation', 'DOI not confirmed', NULL, 2, 0, 'Not retrieved this batch.', 'Derives ACCEPTABILITY BANDS from 27 participants across three populations (manual wheelchair, powered wheelchair, vision impairment using cane or service animal): 1:8 and 1:12 usable and acceptable for most, 1:4 too steep for safe unassisted boarding, and many manual wheelchair users lacked the strength for unassisted ascent. Explicitly frames itself against a proposed federal 1:6 maximum, so it is a code-adequacy argument as well as a usability study. The vision-impairment arm is a NON-MOB lens this corpus has no evidence for.', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:17');
