INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (37, 'REF-00999', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'qualitative', 'ADA-compliant ramp slopes remain the primary factor in incidents and difficulty; compliance does not deliver usability', NULL, 'Despite ADA guidelines, steep ramps remain the primary factor contributing to incidents and difficulty when using ramps to access transit buses.', 'Abstract, Conclusion', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'R7 code-insufficiency finding and the FIRST row in the corpus to use the insufficient relation: the vocabulary existed and the 2026-09-13 owner ruling made such findings first-class evidence, yet no extraction had expressed one. The referent ADA 2010 is held as REF-00987; to_label carries the words the source itself uses, per the named-referent check. Supplies NO value -- it says the code-permitted gradient is not sufficient, not what it should be.', '2026-09-18 04:12', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:12', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (38, 'REF-00999', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'qualitative', 'over 60% of wheelchair users who had a ramp incident identified steep ramp slope as the contributing factor; 22% of those with an incident were injured or had wheelchair damage', NULL, 'Of those who had an incident, 22% were injured or had damage to their wheelchair. Over 60% of those who had an incident identified steep ramp slope as being the contributing factor.', 'Abstract, Results', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'R7 HARM evidence, first-class per the contract. Survey of 384 wheelchair users; 78% had at least one ramp incident in three years (that figure is stated in a separate sentence and is therefore NOT carried in claimed_value here -- the verbatim guard refused an earlier attempt that mixed figures from two sentences, which is the correct behaviour). Steep slope is the user-attributed cause, which is the half a biomechanics study cannot supply.', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (39, 'REF-00977', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, NULL, NULL, 'framework', 'the design of the built environment is itself a factor of disablement; boarding ramps are among the least accessible elements of public space', NULL, 'Pathway characteristics, boarding ramps, entrance features, confined spaces, and service surfaces were deemed to be the least accessible elements.', 'Abstract, Results and Conclusions', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'T2 SYNTHESIS, 48 peer-reviewed studies appraised with the Mixed Methods Appraisal Tool. Filed claim_type=framework because the contribution is an ARGUMENT about causation -- the built environment as a cause of disablement -- rather than a measured quantity. This is the kind of evidence the owner directive of 2026-09-18 requires be captured: highly relevant to ramps, states no value, and carries the reasoning. Its conclusion names the critical role of the design of the built environment as a factor of disablement for MobAD users.', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (40, 'REF-01000', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'GB', NULL, 'qualitative', 'ramp ascent transfers a load of 2 to 3 times body weight through the shoulders, directly linked to shoulder injury', NULL, 'push forces which resulted in a load of 2 to 3 times body weight being transferred through people’s shoulders, forces which can be directly linked to shoulder injury', 'Abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'WHEELCHAIR BIOMECHANICS EVIDENCE ARRIVING FROM A RAMP SEARCH, logged in its own right per the owner directive of 2026-09-18 rather than discarded as context. The harm is iatrogenic to the accommodation: the ramp is the thing being ascended, and the load it imposes can further disable the user by injuring the shoulders they propel with.', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (41, 'REF-01000', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'GB', NULL, 'framework', 'ramps provided as an accessibility solution generate problems of their own', NULL, 'proposed ‘solutions’ to accessibility, such as ramps, often generate problems of their own', 'Abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE ARGUMENT, not a measurement. A mitigation that creates a second impairment pathway is not a partial success but a design failure, and this is the corpus first row stating that as a thesis rather than as an incidental observation. The referent is deliberately unnamed: the paper indicts accessibility solutions as a class, not one named standard. Mixed-methods paper; the companion row (extraction 40) carries its quantified shoulder-load finding. Second use of the insufficient relation.', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:13', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'finding', NULL);
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (20, 37, 'insufficient', NULL, 'ADA guidelines', 'standard', 'named', NULL, 'Despite ADA guidelines, steep ramps remain the primary factor contributing to incidents and difficulty when using ramps to access transit buses.', NULL, '2026-09-18 04:12', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold');
